/**
 * VPN Troubleshooting Knowledge Module
 * Comprehensive knowledge base for diagnosing and fixing VPN-related issues
 * Focuses on Gluetun and common VPN connectivity problems
 */

import { createLogger } from '../utils/logger.js';

const logger = createLogger('vpnKnowledge');

/** Severity level for issues */
export type IssueSeverity = 'critical' | 'high' | 'medium' | 'low' | 'info';

/** VPN provider types */
export type VpnProvider =
    | 'nordvpn'
    | 'mullvad'
    | 'protonvpn'
    | 'surfshark'
    | 'expressvpn'
    | 'privateinternetaccess'
    | 'windscribe'
    | 'torguard'
    | 'airvpn'
    | 'custom'
    | 'wireguard'
    | 'openvpn';

/** Diagnostic step */
export interface DiagnosticStep {
    /** Step number */
    order: number;
    /** Description of what to check */
    description: string;
    /** Command to run (if applicable) */
    command?: string;
    /** Expected result */
    expectedResult?: string;
    /** How to interpret the result */
    interpretation?: string;
}

/** Solution to an issue */
export interface Solution {
    /** Solution title */
    title: string;
    /** Detailed explanation */
    description: string;
    /** Steps to implement the solution */
    steps: string[];

