  1320→/**
  1321→ * Match log output against known patterns
  1322→ */
  1323→export function matchLogPatterns(logOutput: string): ArrInterconnectionIssuePattern[] {
  1324→    const matches: ArrInterconnectionIssuePattern[] = [];
  1325→
  1326→    for (const pattern of ARR_INTERCONNECTION_KB) {
  1327→        if (!pattern.logPatterns) continue;
  1328→
  1329→        for (const logPattern of pattern.logPatterns) {
  1330→            try {
  1331→                const regex = new RegExp(logPattern, 'i');
  1332→                if (regex.test(logOutput)) {
  1333→                    matches.push(pattern);
  1334→                    break; // Only add pattern once even if multiple patterns match
  1335→                }
  1336→            } catch (error) {
  1337→                logger.warn({ logPattern, error: getErrorMessage(error) }, 'Invalid regex pattern');
  1338→            }
  1339→        }
  1340→    }
  1341→
  1342→    logger.debug({ matchCount: matches.length }, 'Log pattern matching completed');
  1343→
  1344→    return matches;
  1345→}
