   119→async function runDiagnosticStep(step: DiagnosticStep): Promise<DiagnosticCheck> {
   120→    if (!step.command) {
   121→        return {
   122→            check: step.description,
   123→            status: 'skip',
   124→            message: 'No command specified',
   125→            expected: step.expectedResult
   126→        };
   127→    }
   128→
   129→    try {
   130→        // Parse command and args
   131→        const parts = step.command.split(/\s+/);
   132→        const command = parts[0];
   133→        const args = parts.slice(1);
   134→
   135→        // Execute with timeout
   136→        const output = await runCommand(command, args, { timeoutMs: 10000 });
   137→
   138→        // Determine if check passed based on output
   139→        let status: DiagnosticCheck['status'] = 'unknown';
   140→        let message = '';
   141→
   142→        if (step.expectedResult) {
   143→            // Simple pattern matching against expected result
   144→            const expectedLower = step.expectedResult.toLowerCase();
   145→            const outputLower = output.toLowerCase();
   146→
   147→            if (expectedLower.includes('should return') || expectedLower.includes('should show')) {
   148→                // Extract what we're looking for
   149→                const lookingFor = expectedLower.split(/should return|should show/)[1]?.trim();
   150→                if (lookingFor && outputLower.includes(lookingFor.replace(/['"]/g, ''))) {
   151→                    status = 'pass';
   152→                    message = 'Output matches expected result';
   153→                } else if (output.trim()) {
   154→                    status = 'fail';
   155→                    message = 'Output does not match expected result';
   156→                } else {
   157→                    status = 'fail';
   158→                    message = 'No output received';
   159→                }
   160→            } else if (output.trim()) {
   161→                status = 'pass';
   162→                message = 'Command executed successfully';
   163→            } else {
   164→                status = 'fail';
   165→                message = 'No output received';
   166→            }
   167→        } else if (output.trim()) {
   168→            status = 'pass';
   169→            message = 'Command executed successfully';
   170→        }
   171→
   172→        return {
   173→            check: step.description,
   174→            status,
   175→            message,
   176→            output: output.trim().substring(0, 500), // Limit output length
   177→            expected: step.expectedResult,
   178→            actual: output.trim().substring(0, 200)
